import {
  CellPropGetter,
  ColumnInstance,
  HeaderGroupPropGetter,
  HeaderPropGetter,
  RowPropGetter,
  TableCellProps,
  TableInstance,
  TablePropGetter,
} from 'react-table';

import { measureCellRef } from './column-size-utils.js';
import { isActionColumn } from '../../utils/column-utils.js';

// Table typings are still based on community types which are not that great,
// need to disable no-explicit-any for the plugin file.
/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/ban-types*/

/** Additional prop getter for the table */
export const getTableProps: TablePropGetter<any> = (props) => {
  return [props];
};

/** Additional prop getter for each row of the table. */
export const getRowProps: RowPropGetter<any> = (props, { instance }) => {
  // If a gridTemplate is defined in the state, we can apply the grid styling,
  // otherwise fall back to the still default flex layout.
  if (instance.state.columnGridTemplate) {
    return [
      props,
      {
        style: {
          display: 'grid',
          gridTemplateColumns: instance.state.columnGridTemplate,
        },
      },
    ];
  }

  return [
    props,
    {
      style: {
        display: 'flex',
        flex: '1 0 auto',
        minWidth: `${instance.totalColumnsMinWidth}px`,
      },
    },
  ];
};

/** Additional prop getter for each header group. */
export const getHeaderGroupProps: HeaderGroupPropGetter<any> = (
  props,
  { instance },
) => {
  // If a gridTemplate is defined in the state, we can apply the grid styling,
  // otherwise fall back to the still default flex layout.
  if (instance.state.columnGridTemplate) {
    return [
      props,
      {
        style: {
          display: 'grid',
          // parent headers share the grid template of child header
          gridTemplateColumns: instance.state.columnGridTemplate,
        },
      },
    ];
  }

  return [
    props,
    {
      style: {
        width: 'fit-content',
        minWidth: '100%',
      },
    },
  ];
};

/** Additional prop getter for each header. */
export const getHeaderProps: HeaderPropGetter<any> = (
  props,
  { column, instance, ...remaining },
) => {
  return addAdditionalProps(props, column, instance);
};

/** Additional prop getter for each cell. */
export const getCellProps: CellPropGetter<any> = (
  props,
  { cell, instance },
) => {
  return addAdditionalProps(props, cell.column, instance);
};

function addAdditionalProps(
  props: any,
  column: ColumnInstance<any>,
  tableInstance: TableInstance<any>,
) {
  // find if the current column is the last column of the visible columns of the instance
  const lastStandardColumn = getLastVisibleStandardColumn(
    tableInstance.visibleColumns,
  );
  const isLastStandardHeaderColumn = getIsLastStandardHeaderColumn(
    lastStandardColumn,
    column,
  );

  // If a gridTemplate is defined in the state, we can apply the grid styling,
  // otherwise fall back to the still default flex layout.
  if (tableInstance.state.columnGridTemplate) {
    let gridColumnEnd: string | undefined;

    if (column.columns) {
      gridColumnEnd = `span ${
        column.columns.filter((column) => column.isVisible).length
      }`;
    }

    // TODO: This needs to be looked into in the future or as we upgrade
    // To fix an issue with placeholder column header props not being
    // applied when updated, this is the solution until a better solution
    // or root cause is found - in this case the prop we are updating
    // is minWidth
    column = column.placeholderOf
      ? tableInstance.headerGroups[1].headers.find(
          (headerGroup) => headerGroup.id === column.placeholderOf?.id,
        ) ?? column
      : column;
    const additionalProps: Partial<TableCellProps> = {
      style: {
        boxSizing: 'border-box',
        minWidth: column.totalMinWidth ?? 0,
        gridColumnEnd,
      },
    };

    // If the column has an autoWidth set, and it has not been measured yet,
    // the measuring logic needs to be added.
    if (column.autoWidth === true) {
      // In order to measure the size of the cell, a Ref can be added. This
      // ref will be called when the native element is rendered.
      // At that time we can take the measurement and report it back to the state.
      additionalProps.ref = measureCellRef(
        tableInstance.state,
        tableInstance.dispatch,
        column.id,
        column.maxWidth ?? Number.MAX_SAFE_INTEGER,
        column.maxAutoWidth ?? Number.MAX_SAFE_INTEGER,
        column.width,
        tableInstance.allColumns,
      );
    }

    const hasRatioWidthsDefined = !!tableInstance?.allColumns.find(
      (column) => column.ratioWidth !== undefined,
    );
    // Make sure each last column takes up at least the default width/defined width/measured autoWidth so it works with grid 'auto'.
    // If the table spans the full width, the last column will stretch to use the remaining space.
    if (
      !hasRatioWidthsDefined &&
      isLastStandardHeaderColumn &&
      additionalProps.style
    ) {
      const { cellWidthsByColumn, isMeasuringInProgress } = tableInstance.state;
      // set minWidth to zero during autoWidth measuring to ensure correct values
      additionalProps.style.minWidth =
        isMeasuringInProgress && column.autoWidth
          ? '0px'
          : `${column.totalWidth || cellWidthsByColumn?.[column.id]}px`;
    }

    return [props, additionalProps];
  }

  const minWidth = column.totalMinWidth;
  // last column styles
  const flexStyles = isLastStandardHeaderColumn
    ? getLastColumnStyle(minWidth)
    : {};

  // Avoid using default maxWidth from tanstack table v7 which is Number.MAX_SAFE_INTEGER
  // https://github.com/TanStack/table/blob/v7/src/publicUtils.js#L16
  const maxWidth =
    column.maxWidth !== Number.MAX_SAFE_INTEGER &&
    column.maxWidth !== undefined &&
    !isLastStandardHeaderColumn
      ? `${column.maxWidth}px`
      : undefined;

  return [
    props,
    {
      style: {
        boxSizing: 'border-box',
        minWidth: `${minWidth}px`,
        width: `${column.totalWidth}px`,
        maxWidth: maxWidth,
        ...flexStyles,
      },
    },
  ];
}

/**
 * Gets final visible column. Excludes action column unless there is no other column.
 * Uses the `tableInstance.visibleColumns` state to get the information.
 * @param visibleColumns - current visibleColumns in the DataTable
 * @returns the column instance of the last column if possible
 */
export function getLastVisibleStandardColumn(
  visibleColumns: ColumnInstance<{}>[] | undefined,
): ColumnInstance<any> | undefined {
  const lastColumn = visibleColumns?.at(-1);
  if (lastColumn && isActionColumn(lastColumn.id)) {
    return visibleColumns?.at(-2);
  } else {
    return lastColumn;
  }
}

function getLastColumnStyle(minWidth: number | undefined): object {
  return { flex: `${minWidth} 0 auto` };
}

/**
 * Checks if a certain column is the last standard header column in either the child or the parent header.
 *
 * @param lastStandardColumn - the last standard column
 * @param column - the column in question
 * @returns a boolean whether it is the last column, excluding the row actions one
 */
function getIsLastStandardHeaderColumn(
  lastStandardColumn?: ColumnInstance<any>,
  column?: ColumnInstance<any>,
): boolean {
  const lastColumnId = lastStandardColumn?.id;
  const lastColumnParentId = lastStandardColumn?.parent?.id;
  // original id is available if it is a placeholder or a parent header (without the _number)
  let columnId = column?.originalId || column?.id;
  // if its a placeholder column, remove that part of the id
  columnId = columnId?.replace(/_placeholder.*/, '');

  return columnId === lastColumnId || columnId === lastColumnParentId;
}
